import{_ as t,c as o,o as s,ag as n}from"./chunks/framework.Bzez9NG9.js";const p=JSON.parse('{"title":"Troubleshooting","description":"Resolve a SPACE version mismatch between the Chrome extension and backend and find the manual extension update steps.","frontmatter":{"title":"Troubleshooting","description":"Resolve a SPACE version mismatch between the Chrome extension and backend and find the manual extension update steps.","keywords":["chrome://extensions","extension update"],"outline":"deep"},"headers":[],"relativePath":"doc/issues.md","filePath":"doc/issues.md"}'),a={name:"doc/issues.md"};function r(i,e,l,h,c,d){return s(),o("div",null,e[0]||(e[0]=[n('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>This guide covers the documented Chrome extension version-mismatch problem. For TM1 server, transaction, and audit evidence, see <a href="./planning-analytics/logs.html">Logs</a>.</p><h2 id="version-mismatch" tabindex="-1">Version mismatch <a class="header-anchor" href="#version-mismatch" aria-label="Permalink to &quot;Version mismatch&quot;">​</a></h2><p>This error occurs when the SPACE backend server version differs from the SPACE extension version. If the extension was recently updated, Google Chrome may take a few hours to sync. To manually update the extension, follow these steps:</p><ol><li>Open <strong>chrome://extensions/</strong> in your browser.</li><li>Enable <strong>Developer mode</strong> (top-right corner).</li><li>Click <strong>Update</strong> (top-left corner).</li></ol><p>This forces Chrome to update all extensions to their latest versions. After updating, refresh your IBM Planning Analytics Workspace page to apply the changes. If the version is still different, please contact your SPACE administrator.</p>',6)]))}const u=t(a,[["render",r]]);export{p as __pageData,u as default};
